/* dropcard — Resonite export.
 *
 * Generated by tools/resonite/browser/bundle.mjs from the modules under tools/resonite/.
 * Do not edit here; edit those and re-run it. The sources are the same ones the Node build
 * and the test harnesses use, so what ships is what was tested.
 */
(function () {
'use strict';

// ──────────────────────── colour.mjs ────────────────────────
// Colour maths shared by the card builder and the icon renderer. Pure arithmetic, no I/O —
// which is what lets the browser export reuse it unchanged.

const hex = ([r, g, b]) =>
  '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');

// Deliberately the plain weighted average rather than the gamma-corrected WCAG relative
// luminance. Every threshold in cardTheme and inkFor was tuned against this curve; swapping in
// the "more correct" one re-picks accents and inks across the whole template set.
const lum = ([r, g, b]) => (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;

const sat = ([r, g, b]) => {
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
  return mx === 0 ? 0 : (mx - mn) / mx;
};

// WCAG-ish contrast, enough to choose between two candidate inks
const contrast = (a, b) => {
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};

// Which ink reads on this backing: the card's paper if it stands out, otherwise plain
// white or near-black. A themed button that cannot be read is not on theme.
function inkFor(backingRGB, theme) {
  const candidates = [theme.surfaceRGB, [255, 255, 255], [17, 17, 24]];
  return hex(candidates.find(c => contrast(c, backingRGB) >= 3.5) ??
             candidates.sort((a, b) => contrast(b, backingRGB) - contrast(a, backingRGB))[0]);
}

// ──────────────────────── pack.mjs ────────────────────────
// Everything needed to write a .resonitepackage from a browser tab, with no dependencies:
// BSON, a Brotli stream, a zip, and SHA-256. The Node builders reach for `bson`,
// `brotli-wasm` and `jszip`; none of those belong in a 7MB single-file app, and two of them
// have no browser build worth shipping.
//
// Runs unchanged in Node 22, which is how it is tested — the same document is encoded here
// and by the Node path, and the two packages are decoded and compared.
//
// The one real constraint: `DataTreeConverter` rejects `Compression.None`, so the object blob
// MUST be LZ4, LZMA or Brotli. See brotliStore below for how that is satisfied without
// shipping a compressor.

const enc = new TextEncoder();

// ── BSON ────────────────────────────────────────────────────────────────────
// Only the types this format actually uses. Values are tagged rather than sniffed, because
// a Double that serialises as an Int32 changes the meaning of a field: `OrderOffset` is an
// Int64 and colour components are Doubles, and the engine reads them by type.
const I32 = v => ({ $t: 'i32', v });
const I64 = v => ({ $t: 'i64', v });
const F64 = v => ({ $t: 'f64', v });

class Buf {
  constructor() { this.b = new Uint8Array(1 << 16); this.n = 0; }
  need(k) { if (this.n + k <= this.b.length) return;
    let cap = this.b.length; while (cap < this.n + k) cap *= 2;
    const next = new Uint8Array(cap); next.set(this.b.subarray(0, this.n)); this.b = next; }
  u8(v) { this.need(1); this.b[this.n++] = v; }
  i32(v) { this.need(4); new DataView(this.b.buffer).setInt32(this.n, v, true); this.n += 4; }
  i64(v) { this.need(8); new DataView(this.b.buffer).setBigInt64(this.n, BigInt(v), true); this.n += 8; }
  f64(v) { this.need(8); new DataView(this.b.buffer).setFloat64(this.n, v, true); this.n += 8; }
  raw(a) { this.need(a.length); this.b.set(a, this.n); this.n += a.length; }
  cstr(s) { this.raw(enc.encode(s)); this.u8(0); }
  out() { return this.b.slice(0, this.n); }
}

function writeDoc(buf, doc, isArray) {
  const start = buf.n;
  buf.i32(0);                                        // length placeholder
  const entries = isArray ? doc.map((v, i) => [String(i), v]) : Object.entries(doc);
  for (const [k, v] of entries) writeElem(buf, k, v);
  buf.u8(0);
  new DataView(buf.b.buffer).setInt32(start, buf.n - start, true);
}

function writeElem(buf, key, v) {
  const put = (type) => { buf.u8(type); buf.cstr(key); };
  if (v === null || v === undefined)      { put(0x0A); return; }
  switch (typeof v) {
    case 'string': { put(0x02); const b = enc.encode(v); buf.i32(b.length + 1); buf.raw(b); buf.u8(0); return; }
    case 'boolean': { put(0x08); buf.u8(v ? 1 : 0); return; }
    case 'number': { put(0x01); buf.f64(v); return; }        // untagged numbers are Doubles
    case 'bigint': { put(0x12); buf.i64(v); return; }
  }
  if (v instanceof Uint8Array) { put(0x05); buf.i32(v.length); buf.u8(0); buf.raw(v); return; }
  if (Array.isArray(v)) { put(0x04); writeDoc(buf, v, true); return; }
  switch (v.$t) {
    case 'i32': put(0x10); buf.i32(v.v); return;
    case 'i64': put(0x12); buf.i64(v.v); return;
    case 'f64': put(0x01); buf.f64(v.v); return;
  }
  put(0x03); writeDoc(buf, v, false);
}

function bson(doc) { const b = new Buf(); writeDoc(b, doc, false); return b.out(); }

// ── Brotli, stored ──────────────────────────────────────────────────────────
// The engine will not accept an uncompressed data tree, but it will accept Brotli — and
// Brotli's own format has an uncompressed meta-block, so a valid stream can be emitted
// without a compressor. That is the whole trick: no WASM blob, no build step.
//
// Per RFC 7932 §9.2, each meta-block here is: ISLAST=0, MNIBBLES=11 (2 bits, value 0),
// MLEN-1 in 16 bits, ISUNCOMPRESSED=1, then padding to a byte boundary and the raw bytes.
// The stream opens with WBITS=16 (1 bit, value 0) and closes with an empty ISLAST block.
//
// It costs about four bytes per 64KB. The object blob is ~14KB of BSON and everything large
// in the package — PNGs, fonts — is stored beside it already compressed, so the difference
// against real Brotli is a few kilobytes on a package of a megabyte or more.
function brotliStore(data) {
  const out = [];
  let acc = 0, nbits = 0;
  const bits = (value, count) => { acc |= value << nbits; nbits += count;
    while (nbits >= 8) { out.push(acc & 0xff); acc >>>= 8; nbits -= 8; } };
  const align = () => { if (nbits > 0) { out.push(acc & 0xff); acc = 0; nbits = 0; } };

  bits(0, 1);                                        // WBITS = 16
  for (let off = 0; off < data.length; off += 0x10000) {
    const chunk = data.subarray(off, Math.min(off + 0x10000, data.length));
    bits(0, 1);                                      // ISLAST = 0
    bits(0, 2);                                      // MNIBBLES = 4 nibbles => 16-bit MLEN
    bits(chunk.length - 1, 16);                      // MLEN - 1
    bits(1, 1);                                      // ISUNCOMPRESSED
    align();
    for (const b of chunk) out.push(b);
  }
  bits(1, 1);                                        // ISLAST = 1
  bits(1, 1);                                        // ISLASTEMPTY = 1
  align();
  return new Uint8Array(out);
}

// ── zip ─────────────────────────────────────────────────────────────────────
const CRC_TABLE = (() => { const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) { let c = i;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[i] = c >>> 0; } return t; })();
const crc32 = (a) => { let c = 0xFFFFFFFF;
  for (let i = 0; i < a.length; i++) c = CRC_TABLE[(c ^ a[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0; };

const deflateRaw = async (bytes) => {
  // `deflate-raw` is exactly the bit stream a zip entry wants — no zlib wrapper to strip
  const cs = new CompressionStream('deflate-raw');
  const buf = await new Response(new Blob([bytes]).stream().pipeThrough(cs)).arrayBuffer();
  return new Uint8Array(buf);
};

async function zip(files) {          // [{ name, bytes }]
  const parts = [], central = [];
  let offset = 0;
  for (const f of files) {
    const nameBytes = enc.encode(f.name);
    const comp = await deflateRaw(f.bytes);
    // a stored entry is smaller than a deflated one for data that is already compressed
    const useDeflate = comp.length < f.bytes.length;
    const body = useDeflate ? comp : f.bytes;
    const method = useDeflate ? 8 : 0;
    const crc = crc32(f.bytes);

    const local = new Uint8Array(30 + nameBytes.length);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, 0x04034b50, true); lv.setUint16(4, 20, true); lv.setUint16(6, 0, true);
    lv.setUint16(8, method, true); lv.setUint16(10, 0, true); lv.setUint16(12, 0, true);
    lv.setUint32(14, crc, true); lv.setUint32(18, body.length, true);
    lv.setUint32(22, f.bytes.length, true); lv.setUint16(26, nameBytes.length, true);
    local.set(nameBytes, 30);
    parts.push(local, body);

    const cen = new Uint8Array(46 + nameBytes.length);
    const cv = new DataView(cen.buffer);
    cv.setUint32(0, 0x02014b50, true); cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
    cv.setUint16(8, 0, true); cv.setUint16(10, method, true);
    cv.setUint32(16, crc, true); cv.setUint32(20, body.length, true);
    cv.setUint32(24, f.bytes.length, true); cv.setUint16(28, nameBytes.length, true);
    cv.setUint32(42, offset, true);
    cen.set(nameBytes, 46);
    central.push(cen);
    offset += local.length + body.length;
  }
  const cenSize = central.reduce((n, c) => n + c.length, 0);
  const end = new Uint8Array(22);
  const ev = new DataView(end.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(8, files.length, true); ev.setUint16(10, files.length, true);
  ev.setUint32(12, cenSize, true); ev.setUint32(16, offset, true);

  const all = [...parts, ...central, end];
  const total = all.reduce((n, a) => n + a.length, 0);
  const outBytes = new Uint8Array(total);
  let p = 0; for (const a of all) { outBytes.set(a, p); p += a.length; }
  return outBytes;
}

const sha256 = async (bytes) => {
  const h = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(h)].map(b => b.toString(16).padStart(2, '0')).join('');
};

// ── the package ─────────────────────────────────────────────────────────────
const FRDT = new Uint8Array([0x46, 0x72, 0x44, 0x54, 0, 0, 0, 0, 0x03]);   // "FrDT" + Brotli

async function buildPackage({ name, types, typeVersions = {}, object, assets = [],
                                     embeddedAssets = [], version = '2026.6.2.275' }) {
  const tv = {};
  for (const t of types) if (typeVersions[t] !== undefined) tv[t] = I32(typeVersions[t]);
  const flags = {};
  for (const k of ['ColorManagement','ResetGUID','ProtoFlux','TEXTURE_QUALITY','TypeManagement',
                   'ALIGNER_FILTERING','PhotonDust','Awwdio','NetCore','RESONITE_LINK']) flags[k] = I32(0);

  const blobBody = bson({ VersionNumber: version, FeatureFlags: flags, Types: types,
                          TypeVersions: tv, Object: object, Assets: assets });
  const compressed = brotliStore(blobBody);
  const blob = new Uint8Array(FRDT.length + compressed.length);
  blob.set(FRDT, 0); blob.set(compressed, FRDT.length);
  const mainHash = await sha256(blob);

  for (const a of embeddedAssets) {
    const got = await sha256(a.bytes);
    if (got !== a.hash) throw new Error(`embedded asset hash mismatch for ${a.hash.slice(0, 12)}`);
  }
  const now = '2026-06-03T00:00:00.0000000Z';
  const record = { id: 'R-Main', ownerId: 'U-JustDalek-', assetUri: `packdb:///${mainHash}`,
    version: { globalVersion: 0, localVersion: 0, lastModifyingUserId: null, lastModifyingMachineId: null },
    name, description: null, recordType: 'object', ownerName: null, tags: null, path: null,
    thumbnailUri: null, lastModificationTime: now, creationTime: now, firstPublishTime: null,
    isDeleted: false, isPublic: false, isForPatrons: false, isListed: false, isReadOnly: false,
    visits: 0, rating: 0, randomOrder: 0, submissions: null,
    assetManifest: embeddedAssets.map(a => ({ hash: a.hash, bytes: a.bytes.length })),
    migrationMetadata: null };

  return zip([
    { name: 'R-Main.record', bytes: enc.encode(JSON.stringify(record)) },
    { name: `Assets/${mainHash}`, bytes: blob },
    ...embeddedAssets.map(a => ({ name: `Assets/${a.hash}`, bytes: a.bytes })),
  ]);
}

// ──────────────────────── raster.mjs ────────────────────────
// Rasterise a DOM subtree to PNG bytes, in the page, with no Playwright.
//
// The Node path screenshots elements through a headless browser. A page has no equivalent,
// so this takes the standard route: clone the subtree into an SVG <foreignObject>, load that
// as an image, draw it to a canvas.
//
// The catch, and the reason this file is mostly plumbing: an SVG loaded as an image is
// SEALED. It cannot reach the network, cannot read the document's stylesheets, and tainting
// rules mean a canvas that draws a cross-origin image cannot be read back. So everything the
// clone needs has to be inlined first — computed styles onto the elements themselves, fonts
// and images as data: URIs. Anything missed does not throw; it silently renders wrong, which
// is why compare.mjs diffs the result against the Playwright output pixel by pixel.

const INHERITED_ONLY = new Set(['cursor', 'pointer-events', 'user-select', '-webkit-user-select']);

// Copying every computed property onto every node is what makes the clone self-contained,
// but it also makes the SVG enormous. Only properties that differ from a default element of
// the same tag are worth writing, which cuts it by roughly an order of magnitude.
const SVG_NS = 'http://www.w3.org/2000/svg';

/* The probe MUST NOT live in the page.
 *
 * "Default" here has to mean the UA default, because the sealed SVG has no author stylesheet —
 * only the inline styles written below. Probing in the live document instead measures the page's
 * own CSS: a single `*{box-sizing:border-box}` rule makes border-box look like the default, so it
 * is skipped as redundant, and every padded box in the clone silently reverts to content-box and
 * grows by its padding. On a card that reads as the inner panel spilling over the frame.
 *
 * A blank same-origin iframe has a browsing context (so getComputedStyle works) and nothing but
 * the UA stylesheet in it. `about:blank` is synchronously scriptable, so no load wait is needed.
 */
function makeProbe(doc) {
  const f = doc.createElement('iframe');
  f.setAttribute('aria-hidden', 'true');
  f.style.cssText = 'position:fixed;left:-10000px;top:0;width:64px;height:64px;border:0;opacity:0;pointer-events:none';
  doc.body.appendChild(f);
  const d = f.contentDocument;
  d.open(); d.write('<!doctype html><html><head></head><body></body></html>'); d.close();
  return { frame: f, doc: d, win: f.contentWindow, cache: new Map() };
}

function defaultsFor(tag, ns, probe) {
  const key = `${ns}|${tag}`;
  let d = probe.cache.get(key);
  if (!d) {
    // An SVG element's defaults are nothing like an HTML element's — `fill`, `stroke` and
    // the geometry properties only exist in the SVG namespace, and createElement('path')
    // makes an HTMLUnknownElement whose computed style would filter out the wrong things.
    let el, host;
    if (ns === SVG_NS) {
      host = probe.doc.createElementNS(SVG_NS, 'svg');
      el = probe.doc.createElementNS(SVG_NS, tag);
      host.appendChild(el); probe.doc.body.appendChild(host);
    } else {
      el = probe.doc.createElement(tag); probe.doc.body.appendChild(el);
    }
    const cs = probe.win.getComputedStyle(el);
    d = {}; for (const p of cs) d[p] = cs.getPropertyValue(p);
    (host ?? el).remove();
    probe.cache.set(key, d);
  }
  return d;
}

const styleText = (cs, def) => {
  let text = '';
  for (const p of cs) {
    if (INHERITED_ONLY.has(p)) continue;
    const v = cs.getPropertyValue(p);
    if (v && v !== def[p]) text += `${p}:${v};`;
  }
  return text;
};

// every family named anywhere in a computed font-family stack, lowercased and unquoted
const noteFamilies = (cs, into) => {
  for (const f of (cs.fontFamily || '').split(','))
    into.add(f.trim().replace(/^["']|["']$/g, '').toLowerCase());
};

// `cloneNode` does not carry ::before / ::after, and the rules that would recreate them are
// gone too — only @font-face survives into the clone. Icon fonts live entirely in those
// pseudo-elements, so without this every glyph on the card silently vanishes: the avatar
// placeholder, the social chips, the decorative marks. Each one becomes a real span.
function addPseudos(src, dst, doc, probe, families) {
  for (const which of ['::before', '::after']) {
    const cs = getComputedStyle(src, which);
    const raw = cs.content;
    if (!raw || raw === 'none' || raw === 'normal') continue;
    noteFamilies(cs, families);      // icon fonts live only here
    const span = doc.createElement('span');
    span.setAttribute('style', styleText(cs, defaultsFor('span', null, probe)) + ';content:normal;');
    // a computed `content` is a quoted string, possibly with \XXXX escapes for a glyph
    const str = /^["'](.*)["']$/s.exec(raw);
    if (str) span.textContent = str[1].replace(/\\([0-9a-fA-F]{1,6})\s?/g,
      (_, hex) => String.fromCodePoint(parseInt(hex, 16)));
    which === '::before' ? dst.prepend(span) : dst.append(span);
  }
}

function inlineStyles(src, dst, doc, probe, families) {
  const cs = getComputedStyle(src);
  noteFamilies(cs, families);
  if (dst.nodeType === 1 && dst.tagName)
    dst.setAttribute('style', styleText(cs, defaultsFor(dst.tagName.toLowerCase(), src.namespaceURI, probe)));
  const sk = src.children, dk = dst.children;
  for (let i = 0; i < sk.length && i < dk.length; i++) inlineStyles(sk[i], dk[i], doc, probe, families);
  if (dst.nodeType === 1) addPseudos(src, dst, doc, probe, families);   // after, so indices stay aligned
}

/* One export rasterises a dozen times — two plates, every graphic, an overlay per contact
   target — and each of those inlines the same handful of font files and images. Fetching and
   base64-ing them once per export rather than once per raster is most of the difference
   between a slow export and a quick one, and none of these can change while it runs. */
const uriCache = new Map();
const asDataURI = (url, mime) => {
  if (!uriCache.has(url)) uriCache.set(url, (async () => {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`${r.status} fetching ${url}`);
    const buf = new Uint8Array(await r.arrayBuffer());
    let bin = ''; for (let i = 0; i < buf.length; i += 0x8000)
      bin += String.fromCharCode.apply(null, buf.subarray(i, i + 0x8000));
    return `data:${mime || r.headers.get('content-type') || 'application/octet-stream'};base64,${btoa(bin)}`;
  })().catch((e) => { uriCache.delete(url); throw e; }));
  return uriCache.get(url);
};

/* The @font-face rules THIS SUBTREE uses, re-declared with their files inlined. Without them
   the clone falls back to a system face and every glyph shifts.
 *
 * Only the families actually named in the clone's computed styles. dropcard declares every
 * typeface it offers plus a full icon font, and inlining the lot put ~9MB of base64 into each
 * SVG — enough that the image simply stopped decoding once anything else was added, which is
 * how the hover overlay came to fail while the card itself squeaked through. A card uses two
 * to four faces; those are the ones that matter, and skipping the rest takes the payload down
 * by well over an order of magnitude. */
async function inlineFonts(doc, families) {
  const seen = new Map();
  for (const sheet of doc.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch { continue; }   // cross-origin sheet
    for (const rule of rules ?? []) {
      if (rule.constructor.name !== 'CSSFontFaceRule') continue;
      const fam = rule.style.getPropertyValue('font-family').trim().replace(/^["']|["']$/g, '').toLowerCase();
      if (!families.has(fam)) continue;
      const key = rule.cssText;
      if (seen.has(key)) continue;
      const m = /url\((['"]?)(https?:[^)'"]+)\1\)/.exec(rule.style.getPropertyValue('src'));
      if (!m) { seen.set(key, rule.cssText); continue; }   // already a data: URI — take it as is
      try { seen.set(key, rule.cssText.replace(m[2], await asDataURI(m[2]))); }
      catch { /* a font we cannot reach is better skipped than fatal */ }
    }
  }
  return [...seen.values()].join('\n');
}

async function inlineImages(root) {
  await Promise.all([...root.querySelectorAll('img')].map(async (img) => {
    if (!img.src || img.src.startsWith('data:')) return;
    try { img.setAttribute('src', await asDataURI(img.src)); }
    catch { img.removeAttribute('src'); }
  }));
}

/**
 * @param el       the element to rasterise
 * @param scale    device pixels per CSS pixel (2 matches the Playwright capture)
 * @param hide     predicate: elements it returns true for are made invisible in the clone,
 *                 which is how the plate is captured without its text and graphics.
 *                 They keep their boxes — see the note at the marking pass below.
 * @returns {Promise<Uint8Array>} PNG bytes with a transparent background
 */
async function rasterise(el, { scale = 2, hide = () => false } = {}) {
  const doc = el.ownerDocument;
  const rect = el.getBoundingClientRect();
  const w = Math.round(rect.width), h = Math.round(rect.height);

  const clone = el.cloneNode(true);
  // Walk both trees together so the predicate sees the ORIGINAL nodes, which still have their
  // ids, dataset and layout — a detached clone has no layout at all.
  //
  // Hidden means INVISIBLE, not absent. Removing a node reflows everything around it: drop the
  // row of social chips off the bottom of a card and the panel above it stretches to take the
  // space, so the plate comes back with its whole layout rearranged. `visibility:hidden` keeps
  // the box and paints nothing, which is what the Node exporter does and therefore what the
  // plate has to be. Marked here and applied after inlineStyles, which would otherwise
  // overwrite the style attribute this sets.
  (function mark(s, d) {
    const sk = [...s.children], dk = [...d.children];
    for (let i = 0; i < sk.length; i++) {
      if (hide(sk[i])) dk[i].setAttribute('data-dc-hidden', '');
      mark(sk[i], dk[i]);
    }
  })(el, clone);
  const probe = makeProbe(doc);
  const families = new Set();
  try { inlineStyles(el, clone, doc, probe, families); } finally { probe.frame.remove(); }
  // Descendants keep no visibility of their own — a computed `visible` matches the tag default
  // and so is never written out — which leaves them inheriting the hidden they sit under.
  for (const n of clone.querySelectorAll('[data-dc-hidden]')) {
    n.setAttribute('style', (n.getAttribute('style') || '') + ';visibility:hidden;');
    n.removeAttribute('data-dc-hidden');
  }
  await inlineImages(clone);
  const fontCss = await inlineFonts(doc, families);

  // The element's own box becomes the viewport, so its position on the page is irrelevant —
  // but it must stay POSITIONED. Dropping to `static` hands every absolutely-positioned
  // descendant a different containing block, and the decorative panels and avatar frame fly
  // off the card. `relative` neutralises the page position without changing what the
  // children resolve against.
  clone.setAttribute('style', (clone.getAttribute('style') || '') +
    `;margin:0;position:relative;left:auto;top:auto;right:auto;bottom:auto;` +
    `transform:none;width:${w}px;height:${h}px;`);

  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` +
    `<defs><style type="text/css">${fontCss.replace(/[<&]/g, c => c === '<' ? '&lt;' : '&amp;')}</style></defs>` +
    `<foreignObject width="100%" height="100%">` +
    `<div xmlns="http://www.w3.org/1999/xhtml">${new XMLSerializer().serializeToString(clone)}</div>` +
    `</foreignObject></svg>`;

  const img = new Image();
  img.decoding = 'sync';
  await new Promise((res, rej) => {
    img.onload = res;
    img.onerror = () => rej(new Error('the SVG clone would not load — something is still ' +
      'referencing the network, or the markup is not well-formed XHTML'));
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  });

  const canvas = doc.createElement('canvas');
  canvas.width = w * scale; canvas.height = h * scale;
  const ctx = canvas.getContext('2d');
  ctx.scale(scale, scale);
  ctx.drawImage(img, 0, 0);

  const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
  return new Uint8Array(await blob.arrayBuffer());
}

// ──────────────────────── fonts.mjs ────────────────────────
// Real TrueType for a family+weight, fetched from a page.
//
// A page cannot set a User-Agent, so Google's css2 endpoint always serves it woff2 — and
// Resonite draws every glyph of a woff2 as a NO GLYPH box, because for an extensionless
// packdb:// URL it sniffs the format from the file's own bytes and does not recognise 'wOF2'.
// That was settled by importing one, not guessed.
//
// The Google Fonts REPOSITORY holds the original TrueType, serves
// `access-control-allow-origin: *`, and its URLs end in .ttf. It is the only source a browser
// can use, so the browser export always takes this route where the Node build defaults to the
// CDN. The cost is that most families are variable-only there, and StaticFont has no variation
// axis — hence scene.mjs's synthetic weight, which thickens the glyphs at the material level.

const STYLE = { 100:'Thin', 200:'ExtraLight', 300:'Light', 400:'Regular', 500:'Medium',
                600:'SemiBold', 700:'Bold', 800:'ExtraBold', 900:'Black' };
const RAW = 'https://raw.githubusercontent.com/google/fonts/main';

// Cards can name a system face (a monospace tag set in "Courier New", say) that Google either
// doesn't host or serves from an extensionless URL. Substitute the nearest family we can
// actually bundle rather than shipping a card with no glyphs.
const FALLBACK = [
  [/mono|courier|consol|menlo/i,             'Space Mono'],
  [/serif|georgia|times|garamond|playfair/i, 'Newsreader'],
  [/./,                                      'Lexend'],
];
const substitute = (family) => (FALLBACK.find(([re]) => re.test(family)) || [, 'Lexend'])[1];

async function fromRepo(family, weight, log) {
  const slug = family.toLowerCase().replace(/[^a-z0-9]/g, '');
  const camel = family.replace(/[^A-Za-z0-9]/g, '');
  const style = STYLE[weight] ?? 'Regular';
  // A static per-weight file first: a variable font imports at its default instance, so a 700
  // run would come out at 400. The variable file is the fallback, not the preference.
  const candidates = [];
  for (const lic of ['ofl', 'apache', 'ufl']) {
    candidates.push(`${lic}/${slug}/static/${camel}-${style}.ttf`);
    candidates.push(`${lic}/${slug}/${camel}-${style}.ttf`);
    candidates.push(`${lic}/${slug}/${camel}%5Bwght%5D.ttf`);
    candidates.push(`${lic}/${slug}/${camel}%5Bopsz,wght%5D.ttf`);
  }
  for (const path of candidates) {
    try {
      const r = await fetch(`${RAW}/${path}`);
      if (!r.ok) continue;
      const bytes = new Uint8Array(await r.arrayBuffer());
      const magic = [...bytes.slice(0, 4)].map(b => b.toString(16).padStart(2, '0')).join('');
      if (magic !== '00010000' && magic !== '4f54544f') continue;   // TrueType / OpenType-CFF
      return { bytes, family, weight, variable: path.includes('%5B') };
    } catch { /* try the next candidate */ }
  }
  const alt = substitute(family);
  if (alt !== family) {
    const viaAlt = await fromRepo(alt, weight, log).catch(() => null);
    if (viaAlt) { log(`${family} ${weight} is not in the fonts repo — using ${alt}`);
                  return { ...viaAlt, substitutedFor: family }; }
  }
  throw new Error(`no TrueType available for ${family} ${weight}`);
}

/** A fetcher with a cache, shaped as scene.mjs's fontFor. */
function fontLoader(log = () => {}) {
  const cache = new Map();
  return (family, weight) => {
    const k = `${family}|${weight}`;
    if (!cache.has(k)) cache.set(k, fromRepo(family, weight, log));
    return cache.get(k);
  };
}

// ──────────────────────── overlay.mjs ────────────────────────
// The card's own colours, and the hover label drawn in them — in the page.
//
// Ports icon.mjs's cardTheme and renderOverlay off pngjs and Playwright. The theme is read
// back out of the plate raster that was just captured, so no template has to declare one.




const b64 = (bytes) => {
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000)
    s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(s);
};

// PNG bytes -> RGBA pixels, without a decoder: the browser has one.
async function pixels(png) {
  const bmp = await createImageBitmap(new Blob([png], { type: 'image/png' }));
  const c = new OffscreenCanvas(bmp.width, bmp.height);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0);
  const d = ctx.getImageData(0, 0, bmp.width, bmp.height).data;
  bmp.close();
  return d;
}

/**
 * The card's paper and accent, read out of the plate.
 * @param bgPng  the front face's plate raster
 * @param job    the capture, for the fallback that reads accent off the text runs
 */
async function cardTheme(bgPng, job) {
  const data = await pixels(bgPng);
  const bins = new Map();
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < 250) continue;
    const k = (data[i] >> 4) * 256 + (data[i + 1] >> 4) * 16 + (data[i + 2] >> 4);
    bins.set(k, (bins.get(k) ?? 0) + 1);
  }
  const unbin = k => [((k / 256) | 0) * 17, (((k / 16) | 0) % 16) * 17, (k % 16) * 17];
  const byCount = [...bins].sort((a, b) => b[1] - a[1]);
  if (!byCount.length) return { surface: '#ffffff', accent: '#111118', surfaceRGB: [255,255,255], accentRGB: [17,17,24] };
  const surface = unbin(byCount[0][0]);

  /* accent: the most saturated colour the card actually spends area on. Near-blacks are
     excluded by the brightness floor — #110000 is technically fully saturated and is just ink.
     Printed bands beat text, because a template's accent is usually a filled area (Ticket's
     header) while its saturated text can be a one-off heading. */
  const total = byCount.reduce((n, [, c]) => n + c, 0);
  const usable = o => sat(o) > 0.28 && Math.max(...o) > 70 && lum(o) < 0.88;
  let accent = byCount.map(([k, c]) => ({ rgb: unbin(k), c }))
    .filter(o => o.c > total * 0.01 && usable(o.rgb))
    .sort((a, b) => sat(b.rgb) - sat(a.rgb))[0]?.rgb;
  if (!accent) {
    accent = Object.values(job.faces).flatMap(f => f.layers || [])
      .filter(L => L.rgba[3] > 0.5)
      .map(L => ({ rgb: L.rgba.slice(0, 3).map(v => v * 255), area: L.w * L.h }))
      .filter(o => usable(o.rgb))
      .sort((a, b) => sat(b.rgb) * Math.sqrt(b.area) - sat(a.rgb) * Math.sqrt(a.area))[0]?.rgb;
  }
  if (!accent) accent = lum(surface) > 0.5 ? [24, 24, 34] : [235, 235, 245];
  return { surface: hex(surface), accent: hex(accent), surfaceRGB: surface, accentRGB: accent };
}

/**
 * The hover overlay that covers an add-contact target. Rendered at the target's own aspect so
 * the quad never stretches it, in the card's accent and its own bundled typeface, so it reads
 * as part of the template rather than as a system tooltip.
 */
async function renderOverlay({ w, h, text = 'Add contact', plate, ink, fontBytes, family }) {
  const scale = 512 / Math.max(w, h);
  const W = Math.round(w * scale), H = Math.round(h * scale);
  const radius = Math.round(Math.min(W, H) * 0.16);
  const pad = Math.round(Math.min(W, H) * 0.1);
  const stack = fontBytes ? `"dc-ov-face", ${family || 'sans-serif'}` : (family || 'sans-serif');

  /* The face is declared as a document @font-face rather than handed to the rasteriser: the
     clone is sealed and can only use faces that are already declared, and raster.mjs passes a
     data: URI src through untouched. Removed again straight after, so it cannot leak into the
     plate captures. */
  const style = document.createElement('style');
  style.textContent = fontBytes
    ? `@font-face{font-family:"dc-ov-face";src:url(data:font/ttf;base64,${b64(fontBytes)}) format("truetype")}`
    : '';
  document.head.appendChild(style);
  if (fontBytes) { try { await document.fonts.load(`16px "dc-ov-face"`); } catch { /* fall back to the stack */ } }

  /* On a squarish target — the avatar frame — one line has to shrink to nothing to fit the
     width. Break it across lines instead, explicitly rather than by letting it wrap, so the
     measuring pass sees exactly the layout the final render will use. */
  const body = (w / h < 2.2) ? text.split(/\s+/) : [text];

  /* Built through the CSSOM rather than an interpolated style="" attribute. A family name is
     quoted — the stack reads `"dc-ov-face", Lexend` — and dropping that into an attribute
     string closes the attribute on its first inner quote, leaving the rest to parse as bare
     attributes. The clone then serialises to markup that is not well-formed XML and the SVG
     silently refuses to load. Assigning the property escapes it properly. */
  const host = document.createElement('div');
  host.style.cssText = 'position:fixed;left:-20000px;top:0;z-index:-1;pointer-events:none';
  const box = document.createElement('div');
  Object.assign(box.style, { width: `${W}px`, height: `${H}px`, borderRadius: `${radius}px`,
    background: plate, display: 'flex', alignItems: 'center', justifyContent: 'center',
    boxSizing: 'border-box', padding: `${pad}px` });
  const span = document.createElement('span');
  Object.assign(span.style, { fontFamily: stack, fontSize: '100px', lineHeight: '1.15',
    color: ink, whiteSpace: 'nowrap', textAlign: 'center', letterSpacing: '0.01em' });
  body.forEach((line, i) => {
    if (i) span.appendChild(document.createElement('br'));
    span.appendChild(document.createTextNode(line));
  });
  box.appendChild(span); host.appendChild(box);
  document.body.appendChild(host);

  try {
    // one measuring pass, because the targets range from a wide name band to a square avatar
    const fit = Math.min((box.clientWidth - pad * 2) / span.offsetWidth,
                         (box.clientHeight - pad * 2) / span.offsetHeight);
    span.style.fontSize = Math.max(8, Math.floor(100 * fit)) + 'px';
    return await rasterise(box, { scale: 1 });
  } finally {
    host.remove();
    style.remove();
  }
}

// ──────────────────────── capture.mjs ────────────────────────
// Read a rendered card face apart into the layers the exporter needs, in the page.
//
// This is the same measurement batch.mjs runs through Playwright, moved into the tab. It gives
// back exactly the shape scene.mjs consumes — { card, layers, links, gfx, avatar } — plus the
// rasters, so the Node capture and this one stay interchangeable and can be diffed.
//
// Nothing here mutates the page for longer than a call takes: the plate is rendered from a
// clone with the text and graphics hidden, never by hiding them in the live DOM.



/* A text run's ELEMENT box is its layout box, routinely the full width of the card or column.
   Sizing a collider to that gives a band across the face that swallows the social chips. Range
   rects give the box the GLYPHS actually occupy, which is what anything clickable is cut to. */
function tightBox(el, R) {
  const rects = [];
  for (const n of el.childNodes) {
    if (n.nodeType !== 3 || !n.textContent.trim()) continue;
    const rg = document.createRange();
    rg.selectNodeContents(n);
    for (const r of rg.getClientRects()) if (r.width > 0 && r.height > 0) rects.push(r);
  }
  if (!rects.length) return null;
  const x0 = Math.min(...rects.map(r => r.left)), y0 = Math.min(...rects.map(r => r.top));
  const x1 = Math.max(...rects.map(r => r.right)), y1 = Math.max(...rects.map(r => r.bottom));
  return { x: x0 - R.x, y: y0 - R.y, w: x1 - x0, h: y1 - y0 };
}

/**
 * Measure one face and rasterise its plate and graphics.
 * @param root  the card face element (#oshi-front-node / #oshi-back-node)
 * @param scale device pixels per CSS pixel; 2 matches what the Node capture produces
 */
async function captureFace(root, { scale = 2, bake = false } = {}) {
  const R = root.getBoundingClientRect();
  const layers = [], gfxEls = [], textEls = [];

  (function walk(el) {
    for (const c of el.children) {
      const own = [...c.childNodes].filter(n => n.nodeType === 3).map(n => n.textContent).join('').trim();
      const r = c.getBoundingClientRect(), cs = getComputedStyle(c);
      if (own && !c.closest('svg') && r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && +cs.opacity > 0) {
        const m = /rgba?\(([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:[,\s/]+([\d.]+))?/.exec(cs.color) || [];
        layers.push({ text: own, x: r.x - R.x, y: r.y - R.y, w: r.width, h: r.height, tight: tightBox(c, R),
          family: (cs.fontFamily.split(',')[0] || '').trim().replace(/^["']|["']$/g, ''),
          fontPx: parseFloat(cs.fontSize), weight: parseInt(cs.fontWeight) || 400, align: cs.textAlign,
          lineHeight: parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2,
          rgba: [(+m[1] || 0) / 255, (+m[2] || 0) / 255, (+m[3] || 0) / 255, m[4] === undefined ? 1 : +m[4]] });
        textEls.push(c);
      }
      walk(c);
    }
  })(root);

  const links = [...root.querySelectorAll('[data-url]')]
    .map(e => { const r = e.getBoundingClientRect();
      return { url: e.dataset.url, network: e.dataset.network || 'link', handle: e.dataset.handle || '',
               x: r.x - R.x, y: r.y - R.y, w: r.width, h: r.height }; })
    .filter(l => /^https?:\/\//i.test(l.url));

  const gfx = [];
  root.querySelectorAll('svg, img').forEach(e => {
    if (e.tagName.toLowerCase() === 'svg' && e.parentElement.closest('svg')) return;
    const r = e.getBoundingClientRect();
    if (r.width < 2 || r.height < 2) return;
    let alpha = 1;
    for (let n = e; n && n !== root.parentElement; n = n.parentElement) {
      const o = parseFloat(getComputedStyle(n).opacity); if (!isNaN(o)) alpha *= o;
    }
    gfx.push({ x: r.x - R.x, y: r.y - R.y, w: r.width, h: r.height, alpha,
               name: (e.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 24) || e.tagName.toLowerCase() });
    gfxEls.push(e);
  });

  /* The avatar region, whether or not a picture was set. A real avatar is an <img>; with none,
     templates draw a placeholder icon-font glyph (ph-user) inside the frame, and the FRAME is
     what we want — the glyph is only 82px inside a 282x250 box. */
  let avatar = null;
  const img = [...root.querySelectorAll('img')]
    .map(e => ({ e, r: e.getBoundingClientRect() }))
    .filter(o => o.r.width > 24 && o.r.height > 24)
    .sort((a, b) => b.r.width * b.r.height - a.r.width * a.r.height)[0];
  if (img) {
    avatar = { x: img.r.x - R.x, y: img.r.y - R.y, w: img.r.width, h: img.r.height, hasImage: true };
  } else {
    /* The GLYPH's own box, not its parent: the parent is the avatar frame in some templates but
       a whole layout column in others (Editorial gives 360x625 on a 1000x625 card, which would
       swallow half the face). The glyph is centred in the frame, so a modest symmetric
       expansion stays inside it whatever the template. */
    const icon = root.querySelector('i[class*="ph-user"], i[class*="ph-person"], i[class*="ph-image"]');
    if (icon) {
      const r = icon.getBoundingClientRect();
      if (r.width > 16 && r.height > 16)
        avatar = { x: r.x - R.x, y: r.y - R.y, w: r.width, h: r.height, hasImage: false, isGlyph: true };
    }
  }

  /* The plate. Standard hides every text run and graphic so neither is baked into it — text
     becomes live TextRenderers in world and each graphic gets its own quad, which is what makes
     the card editable there. Baked keeps them, and then nothing else needs rendering at all.
     The measurements are taken either way: baked still uses them to place the add-contact
     targets, which are colliders rather than artwork. */
  const hidden = new Set([...textEls, ...gfxEls]);
  const bg = await rasterise(root, { scale, hide: bake ? undefined : (n => hidden.has(n)) });
  const gfxPngs = [];
  if (!bake) for (const e of gfxEls) gfxPngs.push(await rasterise(e, { scale }));

  return { data: { card: { w: R.width, h: R.height }, layers, links, gfx, avatar }, bg, gfxPngs };
}

/**
 * Both faces plus the field values the builder needs to recognise the name run.
 * @param fields  { Name, Nickname } as the card is currently showing them
 */
async function captureCard(fields, { scale = 2, bake = false } = {}) {
  const faces = {}, rasters = {};
  for (const side of ['front', 'back']) {
    const el = document.getElementById(`oshi-${side}-node`);
    if (!el) continue;
    const { data, bg, gfxPngs } = await captureFace(el, { scale, bake });
    faces[side] = data;
    rasters[`bg|${side}`] = bg;
    gfxPngs.forEach((p, i) => { rasters[`gfx|${side}|${i}`] = p; });
  }
  // scene.mjs asks for an image more than once and matches by identity, so hand back the
  // same array every time rather than a fresh view
  const imageFor = (kind, side, i) => {
    const key = kind === 'bg' ? `bg|${side}` : `gfx|${side}|${i}`;
    const v = rasters[key];
    if (!v) throw new Error(`no raster captured for ${key}`);
    return v;
  };
  return { faces, fields, imageFor };
}

// ──────────────────────── encoder.mjs ────────────────────────
// The scene encoder, in a browser tab.
//
// Presents exactly the surface scene.mjs expects — the same one protoflux.mjs presents in Node
// — over pack.mjs's dependency-free BSON/Brotli/zip instead of bson/brotli-wasm/jszip.
//
// The only real difference is how a typed value is carried. Node uses the bson classes; here a
// value is a tagged object, `{ $t:'f64', v }`, which pack.mjs writes by tag. Those tags also
// answer to valueOf() and .value, because the facing check reads the numbers back out of the
// tree it is handed and must not care which encoder built it.



const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const NULL_GUID = '00000000-0000-0000-0000-000000000000';

// tagged, but still readable as a number by anything that inspects the tree
const num = (tag, n) => ({ ...tag(n), value: n, valueOf: () => n });

function ProtoFlux() {
  let _id = 0;
  const nextId = () => `${(_id++).toString(16).padStart(8, '0')}-0000-0000-0000-000000000000`;
  const rootId = nextId();   // reserve 00000000 for the ROOT object

  const types = [];
  const typeMap = new Map();
  const typeIndex = (name) => {
    let i = typeMap.get(name);
    if (i === undefined) { i = types.length; types.push(name); typeMap.set(name, i); }
    return num(I32, i);
  };

  const D = (n) => num(F64, n);
  const i32 = (n) => num(I32, n);
  const vec = (...xs) => xs.map(D);
  // A leading '@' marks a URL in the data tree: DataTreeValue.IsURL is true for any string
  // starting with a single '@', and Extract<string> THROWS on one. A plain string beginning
  // with '@' is escaped by doubling it, exactly as DataTreeValue.PreprocessString does on the
  // way out — without this a handle like "@SampleVT" draws nothing at all. Deliberate URLs keep
  // their single '@'; they always carry a scheme, which is what tells the two apart.
  const URL_LIKE = /^@[a-zA-Z][a-zA-Z0-9+.-]*:/;
  const escapeDataTree = (v) =>
    (typeof v === 'string' && v.length > 1 && v[0] === '@' && !URL_LIKE.test(v)) ? '@' + v : v;
  const fd = (data) => ({ ID: nextId(), Data: escapeDataTree(data) });
  const fi = (n) => ({ ID: nextId(), Data: i32(n) });
  const longField = (n) => ({ ID: nextId(), Data: num(I64, n) });
  const list = (items) => items.map((d) => ({ ID: nextId(), Data: d }));

  function component(classpath, fields = {}) {
    const id = nextId();
    const data = { ID: id, 'persistent-ID': nextId(), UpdateOrder: fi(0), Enabled: fd(true) };
    for (const [k, v] of Object.entries(fields)) data[k] = fd(v);
    return { comp: { Type: typeIndex(classpath), Data: data }, id };
  }

  function makeSlot(name, components = [], pos = [0, 0, 0], children = [], tag = null, id = nextId()) {
    const position = fd(vec(pos[0], pos[1], pos[2]));
    const rotation = fd([D(0), D(0), D(0), D(1)]);
    const scale = fd(vec(1, 1, 1));
    return {
      _slot: { id, positionFieldId: position.ID, rotationFieldId: rotation.ID, scaleFieldId: scale.ID },
      ID: id,
      Components: { ID: nextId(), Data: components },
      Name: fd(name), Tag: fd(tag), Active: fd(true), 'Persistent-ID': nextId(),
      Position: position, Rotation: rotation, Scale: scale,
      OrderOffset: longField(0),
      ParentReference: null,                        // Resonite rebuilds parenting from nesting
      Children: children,
    };
  }

  function validate(doc) {
    const defs = new Set(), refs = new Map(), unbound = [];
    const isIdKey = (k) => k === 'ID' || k === 'persistent-ID' || k === 'Persistent-ID' || k.endsWith('-ID');
    const walk = (n, p) => {
      if (n == null || typeof n !== 'object') return;
      if (Array.isArray(n)) return n.forEach((v, i) => walk(v, `${p}[${i}]`));
      for (const [k, v] of Object.entries(n)) {
        if ((k === 'Reference' || k === 'Drive') && v && typeof v === 'object' && 'Data' in v && v.Data === null) unbound.push(`${p}.${k}`);
        if (typeof v === 'string' && GUID.test(v)) {
          if (isIdKey(k)) defs.add(v);
          else if (v !== NULL_GUID && k !== 'ParentReference') refs.set(v, (refs.get(v) ?? 0) + 1);
        } else walk(v, `${p}.${k}`);
      }
    };
    walk(doc.Object, '$');
    walk(doc.Assets, '$.Assets');
    return { defs: defs.size, refs: refs.size,
             dangling: [...refs.keys()].filter((g) => !defs.has(g)), unbound };
  }

  // drop the non-serialised _slot handle; leave tagged values alone, since recursing into one
  // would destructure it into a plain object and lose its type
  function stripHandles(n) {
    if (n == null || typeof n !== 'object') return n;
    if (n.$t) return n;
    if (Array.isArray(n)) return n.map(stripHandles);
    const out = {};
    for (const [k, v] of Object.entries(n)) { if (k === '_slot') continue; out[k] = stripHandles(v); }
    return out;
  }

  async function exportPackage({ name, root, assets = [], embeddedAssets = [],
                                 version = '2026.6.2.275', typeVersions = {} }) {
    const object = stripHandles(root);
    const assetList = stripHandles(assets);
    const report = validate({ Object: object, Assets: assetList });
    if (report.dangling.length)
      throw new Error(`refusing to write a package with ${report.dangling.length} dangling ` +
                      `reference(s): ${report.dangling.map(g => g.slice(0, 8)).join(', ')}`);
    const bytes = await buildPackage({ name, types, typeVersions, object, assets: assetList,
                                       embeddedAssets, version });
    return { bytes, ids: _id, types: types.length, ...report, ok: true };
  }

  return { nextId, id: nextId, rootId, typeIndex, D, i32, vec, fd, fi, longField, list,
           component, makeSlot, validate, exportPackage };
}

// Same shape build_batch.mjs's newEncoder returns, so scene.mjs is handed the same thing.
function newEncoder() {
  const pf = ProtoFlux();
  const assets = [], embeds = [];
  const asset = (cp, f = {}) => {
    const id = pf.nextId();
    const data = { ID: id, persistent: pf.fd(true), UpdateOrder: pf.fi(0), Enabled: pf.fd(true) };
    for (const [k, v] of Object.entries(f)) data[k] = pf.fd(v);
    return { entry: { Type: pf.typeIndex(cp), Data: data }, id };
  };
  return { pf, asset, assets, embeds };
}

// ──────────────────────── scene.mjs ────────────────────────
// The card scene: one .resonitepackage-shaped slot tree, built from a captured face set.
//
// Deliberately free of Node and of the DOM. Everything environment-specific arrives as an
// argument, so the same construction runs in the build script and in the browser tab:
//
//   pf, asset, assets, embeds  the encoder (protoflux.mjs in Node, browser/encoder.mjs in a page)
//   imageFor(kind, side, i)    PNG bytes: kind is 'bg' or 'gfx'. MUST return the same array
//                              each time it is asked for the same thing — see the hash pass.
//   sha256(bytes)              async hex digest
//   fontFor(family, weight)    async -> { bytes, variable }
//   overlayFor({...})          async -> PNG bytes for a hover label, or omit for none
//   theme                      { surfaceRGB, accentRGB } for those overlays, or omit
//   userId                     baked into every ContactLink; normally '' and filled by the dispenser
//
// The two drivers are build_batch.mjs (Playwright + files) and browser/export.mjs (in-page).


const FE = '[FrooxEngine]FrooxEngine.';
const CP = { ObjectRoot:FE+'ObjectRoot', Grabbable:FE+'Grabbable', BoxCollider:FE+'BoxCollider',
  QuadMesh:FE+'QuadMesh', MeshRenderer:FE+'MeshRenderer', Unlit:FE+'UnlitMaterial',
  Hyperlink:FE+'Hyperlink', StaticTexture2D:FE+'StaticTexture2D', TextRenderer:FE+'TextRenderer',
  TextUnlit:FE+'TextUnlitMaterial', StaticFont:FE+'StaticFont',
  ContactLink:FE+'ContactLink', TouchButton:FE+'TouchButton',
  BoolDriver:FE+'ValueDriver<bool>' };
const TV = { [CP.Grabbable]:2, [CP.BoxCollider]:1, [CP.QuadMesh]:1, [CP.TextRenderer]:5 };

const LONG_EDGE = 0.1712;   // the card's long side, whatever its orientation
const CARD_GAP = 0.0001, COLLIDER_T = 0.002;
const Q_PLATE = 3000, Q_GFX = 3050, Q_TEXT = 3100;
const TEXT_Z = 6, GFX_Z = 3, LINK_Z = 4, LINK_DEPTH = 4;
const CONTACT_Z = 5, CONTACT_DEPTH = 4, OVERLAY_Z = 9, Q_OVERLAY = 3150;
const SHIELD_Z = 1, SHIELD_DEPTH = 1.6, SHIELD_PAD = 2;
const CONTACT_PADS = [8, 4, 0];   // comfort margin, in card px, largest that still fits
// Every touch collider stays on its own face's side of the card — it sits Z px in front of
// its face and is DEPTH px thick, so DEPTH < 2*Z. This keeps the boxes from poking out of
// the far side when you visualise them; it does NOT stop a click reaching through (see the
// shield comment below — nothing does, at this thickness). Shields must also sit NEARER the
// card than the buttons of their own face, or they would shadow them.
for (const [what, z, d] of [['link', LINK_Z, LINK_DEPTH], ['contact', CONTACT_Z, CONTACT_DEPTH],
                            ['shield', SHIELD_Z, SHIELD_DEPTH]])
  if (d >= 2 * z) throw new Error(`${what} collider depth ${d} punches through the card at z=${z}`);
if (SHIELD_Z + SHIELD_DEPTH / 2 >= Math.min(LINK_Z, CONTACT_Z) - Math.max(LINK_DEPTH, CONTACT_DEPTH) / 2)
  throw new Error('shields reach out past this face\'s own buttons and would shadow them');
const SIZE_GAIN = 10, LH_BASIS = 0.8 / 1.2;
const ALIGN = { left:'Left', center:'Center', right:'Right', justify:'Justify', start:'Left', end:'Right' };
const slug = t => (t.replace(/\s+/g,' ').trim().slice(0,24) || 'Text');

// ── FACING ──────────────────────────────────────────────────────────────────
// Read this before adding anything visible. Three separate elements have shipped mirrored,
// and every time the cause was the same: a rotation constant copied from a neighbour that
// sat at a DIFFERENT DEPTH in the slot tree. The rule is not local, so it cannot be authored
// by copying — it depends on the product of every ancestor's rotation.
//
// A quad or a TextRenderer whose ancestors and own mesh rotation compose to identity faces
// -Z; one that composes to 180-about-Y faces +Z. Either is fine on its own — what makes it
// read mirrored is facing AWAY from the side of the card it sits on. So the whole rule is:
//
//     net rotation is 180-about-Y  <=>  the element sits at z > 0
//
// which `assertFacing` checks on the finished tree, on every build, for every element. That
// check is the fix; this comment is only here to explain it. Practical consequence: below a
// face slot, exactly ONE 180 must appear between the face and the pixels. `px()` supplies it
// for everything under it, so those quads take NO_ROT; a quad parented straight to the face
// supplies its own with Y180.
const Y180 = D => [D(0), D(1), D(0), D(0)];
const NO_ROT = D => [D(0), D(0), D(0), D(1)];
// how a call site says where it sits, so the reader never has to count 180s
const UNDER_PX = false, ON_THE_FACE = true;
const isY180 = r => r && Math.abs(Number(r[1]) - 1) < 1e-6 && Math.abs(Number(r[3])) < 1e-6;

function assertFacing(root, pf, label = 'object') {
  const idx = cp => pf.typeIndex(cp).value;                 // typeIndex is idempotent
  const T = { quad: idx(CP.QuadMesh), rend: idx(CP.MeshRenderer), text: idx(CP.TextRenderer) };
  const quadRot = new Map();
  (function collect(s) {
    for (const c of s.Components.Data)
      if (c.Type.value === T.quad) quadRot.set(c.Data.ID, c.Data.Rotation?.Data);
    for (const c of s.Children) collect(c);
  })(root);

  const bad = [];
  (function walk(s, parity, z, scaleZ, path) {
    // only the ancestors' flip parity decides the SIGN of a local z offset
    const worldZ = z + (parity % 2 ? -1 : 1) * Number(s.Position.Data[2]) * scaleZ;
    const mine = parity + (isY180(s.Rotation.Data) ? 1 : 0);
    const myScale = scaleZ * Number(s.Scale.Data[2]);
    const here = `${path}/${s.Name.Data}`;
    const check = (p, what) => {
      const wantPositiveZ = p % 2 === 1;
      if (Math.abs(worldZ) < 1e-9 || (worldZ > 0) !== wantPositiveZ)
        bad.push(`${here} (${what}) faces ${wantPositiveZ ? '+Z' : '-Z'} but sits at ` +
                 `z=${(worldZ * 1000).toFixed(2)}mm — it will read MIRRORED`);
    };
    for (const c of s.Components.Data) {
      if (c.Type.value === T.text) check(mine, 'TextRenderer');
      if (c.Type.value === T.rend) {
        const rot = quadRot.get(c.Data.Mesh?.Data);
        if (rot !== undefined) check(mine + (isY180(rot) ? 1 : 0), 'quad');
      }
    }
    for (const c of s.Children) walk(c, mine, worldZ, myScale, here);
  })(root, 0, 0, 1, '');

  if (bad.length) throw new Error(`facing check failed on ${label}:\n  ` + bad.join('\n  '));
  return true;
}

// A variable font imports at its default instance, so Cormorant Garamond 400 and 700 are the
// same file and the engine draws them identically — confirmed in-world, headings came out the
// same weight as body copy. FaceDilate thickens MSDF glyphs at the material level and the
// engine uses it for its own UI text (0.2-0.4), so it can stand in for the missing cut.
// Only ever applied when the file cannot supply the weight itself; with a per-weight static
// from the CDN this is zero and the real cut does the work.
const DILATE_PER_100 = 0.05;
const dilateFor = (weight, variable) =>
  variable ? Math.max(0, (weight - 400)) / 100 * DILATE_PER_100 : 0;

/* bake: merge the card's own artwork into the plate instead of rebuilding it.
 *
 * Standard keeps every element separate — each text run is a live TextRenderer and each graphic
 * its own quad — so the card can be edited in world. Baked hands over the face as it was drawn:
 * one texture per side, nothing to take apart. imageFor must supply a plate rendered with the
 * text and graphics VISIBLE for that to be true, which is the browser capture's 'baked' mode.
 *
 * What is not visual stays either way: the links, the add-contact targets and the shields are
 * colliders, and baking artwork is no reason to stop the card working. It also means a baked
 * export needs no typefaces at all — nothing draws glyphs — so it makes no network requests. */
async function cardRoot({ pf, asset, assets, embeds, job, imageFor, sha256, fontFor,
                                overlayFor = null, theme = null, userId = '', bake = false,
                                log = () => {} }) {
  const faces = job.faces;
  const PX_W = faces.front.card.w, PX_H = faces.front.card.h;
  const S = LONG_EDGE / Math.max(PX_W, PX_H);
  const CARD_W = PX_W * S, CARD_H = PX_H * S;

  const D = pf.D;

  const wanted = new Map();
  if (!bake) for (const s of Object.keys(faces)) for (const L of faces[s].layers) wanted.set(`${L.family}|${L.weight}`, L);
  const fonts = new Map(), isVariable = new Map();
  for (const [k, L] of wanted) {
    const { bytes, variable } = await fontFor(L.family, L.weight);
    isVariable.set(k, variable);
    const hash = await sha256(bytes);
    const a = asset(CP.StaticFont, { URL:`@packdb:///${hash}`, Padding:pf.i32(4),
      PixelRange:pf.i32(4), GlyphEmSize:pf.i32(64), MipMaps:true });
    assets.push(a.entry);
    if (!embeds.some(e => e.hash === hash)) embeds.push({ hash, bytes });
    fonts.set(k, a);
  }
  // one material per distinct dilation, so a card with three weights costs three materials
  const textMats = new Map();
  const textMat = (dilate = 0) => {
    const k = dilate.toFixed(3);
    if (!textMats.has(k)) {
      const m = asset(CP.TextUnlit, {
        TintColor:[D(1),D(1),D(1),D(1),'sRGB'], OutlineColor:[D(0),D(0),D(0),D(0),'sRGB'],
        BackgroundColor:[D(0),D(0),D(0),D(0),'sRGB'], AutoBackgroundColor:false,
        GlyphRenderMethod:'MSDF', PixelRange:D(4), FaceDilate:D(dilate), OutlineThickness:D(0),
        FaceSoftness:D(0), BlendMode:'Alpha', Sidedness:'Double', ZWrite:'Auto',
        RenderQueue:pf.i32(Q_TEXT) });
      assets.push(m.entry); textMats.set(k, m);
    }
    return textMats.get(k);
  };

  // ownFlip: does this quad supply its OWN 180-about-Y? See FACING below — everything under a
  // face must contribute exactly one, and the `px` wrapper already supplies it for its children.
  // Deliberately has no default: a wrong guess here is invisible until someone reads the
  // card in VR, so a new call site must say where it sits.
  function texturedQuad(png, { w, h, tint=[1,1,1,1], queue, ownFlip }) {
    if (ownFlip === undefined) throw new Error('texturedQuad needs an explicit ownFlip');
    const hash = hashOf(png);
    const tex = asset(CP.StaticTexture2D, { URL:`@packdb:///${hash}`, Uncompressed:false,
      DirectLoad:false, ForceExactVariant:false, PreferredProfile:'sRGB', MipMapBias:D(0),
      IsNormalMap:false, WrapModeU:'Clamp', WrapModeV:'Clamp', PowerOfTwoAlignThreshold:D(0.05),
      CrunchCompressed:false, MipMaps:true, KeepOriginalMipMaps:false, MipMapFilter:'Box', Readable:false });
    const mat = asset(CP.Unlit, { TintColor:[D(tint[0]),D(tint[1]),D(tint[2]),D(tint[3]),'sRGB'],
      Texture:tex.id, BlendMode:'Alpha', AlphaCutoff:D(0.5), UseVertexColors:false,
      ZWrite: queue===Q_PLATE ? 'On' : 'Auto', RenderQueue:pf.i32(queue) });
    assets.push(tex.entry, mat.entry);
    if (!embeds.some(e => e.hash === hash)) embeds.push({ hash, bytes:png });
    const quad = pf.component(CP.QuadMesh, { Rotation: ownFlip ? Y180(D) : NO_ROT(D), Size:[D(w),D(h)],
      UVOffset:[D(0),D(0)], UVScale:[D(1),D(1)], ScaleUVWithSize:false });
    const rend = pf.component(CP.MeshRenderer, { Mesh:quad.id, Materials:pf.list([mat.id]),
      MaterialPropertyBlocks:[], ShadowCastMode:'On', SortingOrder:pf.i32(0) });
    return [quad.comp, rend.comp];
  }

  const textSlot = (L,i) => pf.makeSlot(`${String(i+1).padStart(2,'0')} ${slug(L.text)}`,
    [pf.component(CP.TextRenderer, {
      Text:L.text, ParseRichText:false, NullText:null, Size:D(L.fontPx*SIZE_GAIN),
      HorizontalAlign:ALIGN[L.align] ?? 'Left', VerticalAlign:'Middle', AlignmentMode:'Geometric',
      Color:[D(L.rgba[0]),D(L.rgba[1]),D(L.rgba[2]),D(L.rgba[3]),'sRGB'],
      Materials:pf.list([textMat(dilateFor(L.weight, isVariable.get(`${L.family}|${L.weight}`))).id]),
      LineHeight:D((L.lineHeight/L.fontPx)*LH_BASIS),
      Bounded:true, BoundsSize:[D(L.w),D(L.h)], BoundsAlignment:'MiddleCenter',
      MaskPattern:null, HorizontalAutoSize:false, VerticalAutoSize:false,
      Font:fonts.get(`${L.family}|${L.weight}`).id }).comp],
    [ (L.x+L.w/2)-PX_W/2, -((L.y+L.h/2)-PX_H/2), -TEXT_Z ]);

  const linkSlot = (L,i) => pf.makeSlot(`${String(i+1).padStart(2,'0')} ${L.network}${L.handle?' '+L.handle:''}`,
    [ pf.component(CP.BoxCollider, { Size:[D(L.w),D(L.h),D(LINK_DEPTH)], Type:'Static',
        Mass:D(0.1), CharacterCollider:false, IgnoreRaycasts:false }).comp,
      pf.component(CP.Hyperlink, { URL:`@${L.url}`, OpenOnce:false, Reason:`dropcard link — ${L.network}` }).comp ],
    [ (L.x+L.w/2)-PX_W/2, -((L.y+L.h/2)-PX_H/2), -LINK_Z ]);

  const gfxSlot = side => (g,i) => pf.makeSlot(`${String(i+1).padStart(2,'0')} ${g.name||'graphic'}`,
    texturedQuad(imageFor('gfx', side, i),
      { w:g.w, h:g.h, tint:[1,1,1,g.alpha ?? 1], queue:Q_GFX, ownFlip:UNDER_PX }),
    [ (g.x+g.w/2)-PX_W/2, -((g.y+g.h/2)-PX_H/2), -GFX_Z ]);

  // Add-contact lives on the name and the profile picture rather than a separate button:
  // no template needs a reserved spot, and it cannot cover the social chips. Identified by
  // VALUE (the name field's text, the avatar's <img>) so no template markers are required.
  //
  // TouchButton is the slot's ITouchable — two ITouchables cannot share a slot, since
  // RaycastTouchSource resolves a single GetComponentInParentsUntilBlock — but ContactLink
  // does not need to be one: TouchButton dispatches its press to every IButtonPressReceiver
  // on its own slot (TouchButton.cs:186), and ContactLink is one. UserId is left EMPTY here;
  // the instancer bakes it in once it knows who owns the card.
  const contactTargets = (side) => {
    const f = faces[side], out = [];
    // A text run's ELEMENT box is its layout box, routinely the full width of the card or
    // column; sizing a collider to that gives a band across the face that swallows the
    // social chips. `tight` is the box the glyphs actually occupy.
    const glyphBox = L => L.tight || { x:L.x, y:L.y, w:L.w, h:L.h };
    const grow = (b, p) => ({ x:b.x-p, y:b.y-p, w:b.w+2*p, h:b.h+2*p });
    const hit = (a, b) => a.x < b.x+b.w && b.x < a.x+a.w && a.y < b.y+b.h && b.y < a.y+a.h;
    // trim b just far enough on its least-buried side to clear o
    const clip = (b, o) => {
      const cut = [[o.x+o.w-b.x,'L'], [b.x+b.w-o.x,'R'], [o.y+o.h-b.y,'T'], [b.y+b.h-o.y,'B']]
        .sort((p, q) => p[0]-q[0])[0];
      if (cut[0] <= 0) return b;
      if (cut[1]==='L') return { ...b, x:b.x+cut[0], w:b.w-cut[0] };
      if (cut[1]==='R') return { ...b, w:b.w-cut[0] };
      if (cut[1]==='T') return { ...b, y:b.y+cut[0], h:b.h-cut[0] };
      return { ...b, h:b.h-cut[0] };
    };
    // Comfortable but never overlapping: take the largest pad that clears every neighbour,
    // and if even the bare box collides, trim it. Colliders may be bigger than their
    // element; they may not reach into the next one.
    const fit = (base, near) => {
      for (const p of CONTACT_PADS) {
        const b = grow(base, p);
        if (!near.some(o => hit(b, o))) return b;
      }
      let b = { ...base };
      for (const o of near) if (hit(b, o)) b = clip(b, o);
      return (b.w > 8 && b.h > 8) ? b : null;
    };

    const names = [job.fields?.Name, job.fields?.Nickname]
      .filter(Boolean).map(v => v.trim().toLowerCase());
    const texts = (f.layers || []).map(glyphBox);
    if (names.length) {
      (f.layers || []).forEach((L, i) => {
        if (!names.includes(L.text.trim().toLowerCase())) return;
        const near = [...texts.filter((_, j) => j !== i), ...(f.links || []), ...out];
        const b = fit(glyphBox(L), near);
        if (b) out.push({ ...b, what:'name' });
      });
    }
    // The avatar region is a contact target whether or not a picture was set — with none,
    // templates still draw a placeholder inside the frame, so there is something to aim at.
    if (f.avatar) {
      const a = f.avatar;
      // a placeholder glyph is small; grow it into a comfortable target, but only as far as
      // the nearest other clickable/drawn item allows, so it can never cover one
      let box = { ...a };
      if (a.isGlyph) {
        const GROW = 1.9, CAP = 260;
        const w = Math.min(a.w * GROW, CAP), h = Math.min(a.h * GROW, CAP);
        const wide = { x: a.x + a.w/2 - w/2, y: a.y + a.h/2 - h/2, w, h };
        const clash = [...texts, ...(f.gfx||[]), ...(f.links||[]), ...out].some(r => hit(wide, r));
        if (!clash) box = wide;             // otherwise stay on the glyph rather than overlap
      }
      if (!out.some(o => hit(box, o)))
        out.push({ ...box, what: a.hasImage ? 'photo' : 'photo (placeholder)' });
    }
    // and never off the edge of the card, where a click would land on nothing
    const W = f.card.w, H = f.card.h;
    return out.map(t => { const x = Math.max(0, t.x), y = Math.max(0, t.y);
      return { ...t, x, y, w: Math.min(t.w + t.x - x, W - x), h: Math.min(t.h + t.y - y, H - y) };
    }).filter(t => t.w > 8 && t.h > 8);
  };

  // Field IDs of every ContactLink.UserId, so the instancer can bake the owner into them.
  // A component ID is not enough: writing a field needs the FIELD's id.
  const userIdFields = [];
  const contactSlot = (t, i) => {
    // Normally empty — the instancer bakes it in once it knows the owner. Set
    // DROPCARD_USERID to hardcode one for testing the click end to end.
    const link = pf.component(CP.ContactLink, { UserId: userId });
    userIdFields.push(link.comp.Data.UserId.ID);
    // IsHovering has to be written out explicitly: this encoder serialises only the fields it
    // is given, and an unserialised sync member has no ID for the driver to point at.
    const touch = pf.component(CP.TouchButton, { AcceptPhysicalTouch:true, AcceptRemoteTouch:true,
      AcceptOutOfSightTouch:false, IsHovering:false, IsPressed:false });
    const comps = [
      pf.component(CP.BoxCollider, { Size:[D(t.w),D(t.h),D(CONTACT_DEPTH)], Type:'Static',
        Mass:D(0.1), CharacterCollider:false, IgnoreRaycasts:false }).comp,
      touch.comp, link.comp ];
    const kids = [];
    // The overlay is a plain textured quad — no UIX on the card. It sits in front of the
    // card's own text, starts inactive, and a ValueDriver turns it on straight from
    // TouchButton.IsHovering: no ProtoFlux, so a card works on its own away from a dispenser.
    if (t.overlay) {
      const ov = pf.makeSlot('Add contact (on hover)',
        texturedQuad(t.overlay, { w:t.w, h:t.h, queue:Q_OVERLAY, ownFlip:UNDER_PX }),
        [0, 0, -(OVERLAY_Z-CONTACT_Z)]);
      ov.Active.Data = false;
      kids.push(ov);
      comps.push(pf.component(CP.BoolDriver, { ValueSource: touch.comp.Data.IsHovering.ID,
        DriveTarget: ov.Active.ID }).comp);
    }
    return pf.makeSlot(`${String(i+1).padStart(2,'0')} add contact — ${t.what}`, comps,
      [ (t.x+t.w/2)-PX_W/2, -((t.y+t.h/2)-PX_H/2), -CONTACT_Z ], kids);
  };

  const contacts = { front: contactTargets('front'), back: faces.back ? contactTargets('back') : [] };

  // Hover overlays, in the card's own accent and typeface. Optional: with no renderer the
  // targets still work, they just carry no label on hover.
  if (overlayFor && theme) {
    const ink = inkFor(theme.accentRGB, theme);
    const plate = `rgba(${theme.accentRGB.join(',')},0.93)`;
    // the typeface the card spends the most area in, so the overlay matches its voice
    const byArea = new Map();
    for (const f of Object.values(faces)) for (const L of f.layers || [])
      byArea.set(`${L.family}|${L.weight}`, (byArea.get(`${L.family}|${L.weight}`) ?? 0) + L.w * L.h);
    const [fam, wgt] = ([...byArea].sort((a, b) => b[1] - a[1])[0]?.[0] ?? 'Lexend|500').split('|');
    // .bytes, not the record: this used to hand the whole { bytes, variable } across, which
    // stringifies to "[object Object]" inside the data: URL, so the face never loaded and the
    // overlay quietly fell back to a system font.
    // Baked cards embed no typeface, so there are no bytes to hand the label — the renderer
    // falls back to the face the page already has, which is the one the card is drawn in.
    const face = bake ? { bytes: null } : await fontFor(fam, +wgt);
    for (const side of Object.keys(contacts)) for (const t of contacts[side])
      t.overlay = await overlayFor({ w:t.w, h:t.h, plate, ink, fontBytes:face.bytes, family:fam });
  }

  /* Every raster the tree references, hashed before the tree is built.
     Content addressing is what ties a component to its bytes (`@packdb:///<sha256>`), and the
     web has no synchronous digest — crypto.subtle is promise-only. Rather than make the whole
     tree construction async, hash the images up front and look them up by reference while
     building. imageFor MUST therefore return the same array for the same arguments; both
     drivers cache for that reason. */
  const pngs = [];
  for (const side of Object.keys(faces)) {
    if (!faces[side]) continue;
    pngs.push(imageFor('bg', side));
    // baked draws no separate graphics, so none were rendered to hash
    if (!bake) (faces[side].gfx || []).forEach((_, i) => pngs.push(imageFor('gfx', side, i)));
  }
  for (const side of Object.keys(contacts)) for (const t of contacts[side]) if (t.overlay) pngs.push(t.overlay);
  const hashes = new Map();
  for (const p of pngs) if (!hashes.has(p)) hashes.set(p, await sha256(p));
  const hashOf = (p) => {
    const h = hashes.get(p);
    if (!h) throw new Error('an image reached texturedQuad that was never hashed — imageFor ' +
                            'must return the same array each time it is asked for one');
    return h;
  };

  // Standing off from the card does NOT stop a click reaching the far face, and neither does
  // putting plain geometry in the way: RaycastTouchSource walks EVERY hit in distance order
  // and skips the ones with no ITouchable above them, giving up only once it is
  // MaxTouchPenetrationDistance past the first hit — 10mm on the laser, 50mm by default.
  // The card is 4mm deep, buttons included. Nothing inert can shadow anything.
  //
  // So each face carries a SHIELD: a TouchButton with no receivers, at the mirrored footprint
  // of every button on the OTHER face, sitting nearer the card than this face's own buttons.
  // It is the first touchable the ray meets there, and it does nothing, so the far face's
  // add-contact is unreachable while this face's own buttons still win where they overlap.
  // Only the far side's footprints are covered, so the rest of the card still reads as
  // grabbable rather than as one card-sized button.
  const shieldsFor = side => {
    const other = side === 'front' ? 'back' : 'front';
    if (!faces[other]) return [];
    return [...contacts[other], ...(faces[other].links || [])]
      .map(b => ({ x: PX_W - (b.x + b.w) - SHIELD_PAD, y: b.y - SHIELD_PAD,
                   w: b.w + 2*SHIELD_PAD, h: b.h + 2*SHIELD_PAD }));
  };

  const shieldSlot = (b, i) => pf.makeSlot(`${String(i+1).padStart(2,'0')} shields the other face`,
    [ pf.component(CP.BoxCollider, { Size:[D(b.w),D(b.h),D(SHIELD_DEPTH)], Type:'Static',
        Mass:D(0.1), CharacterCollider:false, IgnoreRaycasts:false }).comp,
      pf.component(CP.TouchButton, { AcceptPhysicalTouch:true, AcceptRemoteTouch:true,
        AcceptOutOfSightTouch:false }).comp ],
    [ (b.x+b.w/2)-PX_W/2, -((b.y+b.h/2)-PX_H/2), -SHIELD_Z ]);

  const touchReport = [];
  function faceSlot(side, z, flip) {
    const f = faces[side]; if (!f) return null;
    const px = (name, kids) => { const r = pf.makeSlot(name, [], [0,0,0], kids);
      r.Scale.Data=[D(S),D(S),D(S)]; r.Rotation.Data=Y180(D); return r; };
    const kids = [ pf.makeSlot('Background',
      texturedQuad(imageFor('bg', side),
        { w:CARD_W, h:CARD_H, queue:Q_PLATE, ownFlip:ON_THE_FACE }), [0,0,0]) ];
    // baked: the plate already carries both, so rebuilding them would double them up
    if (!bake && f.gfx?.length)   kids.push(px('Graphics', f.gfx.map(gfxSlot(side))));
    if (!bake && f.layers.length) kids.push(px('Text', f.layers.map(textSlot)));
    if (f.links?.length) kids.push(px('Links', f.links.map(linkSlot)));
    const ct = contacts[side];
    if (ct.length) { touchReport.push(...ct.map(t => ({ side, ...t })));
                     kids.push(px('Add contact', ct.map(contactSlot))); }
    const sh = shieldsFor(side);
    if (sh.length) kids.push(px('Shields', sh.map(shieldSlot)));
    const s = pf.makeSlot(side==='front'?'Front':'Back', [], [0,0,z], kids);
    if (flip) s.Rotation.Data=Y180(D);
    return s;
  }

  const root = pf.makeSlot(`dropcard — ${job.template}`, [
    pf.component(CP.ObjectRoot, {}).comp,
    pf.component(CP.Grabbable, { Scalable:true }).comp,
    pf.component(CP.BoxCollider, { Size:[D(CARD_W),D(CARD_H),D(COLLIDER_T)], Type:'Static', Mass:D(0.1) }).comp,
  // The FRONT faces -Z, which is what greets you on import. A spawned slot is given
  // `rotation = LocalUserViewRotation` (SlotPositioning.PositionInFrontOfUser), and the view
  // rotation's +Z points where you are looking — away from you. So +Z is the side you never
  // see first, and a card whose front faced +Z always landed showing its back.
  // Swapping the two (z, flip) pairs rotates the whole card; each face's own subtree turns
  // with its plate, so nothing inside it is mirrored by this.
  ], [0,0,0], [faceSlot('front', -CARD_GAP/2, true), faceSlot('back', CARD_GAP/2, false)].filter(Boolean),
     null);

  // Runs on every card, every build. This is what stops a fourth mirrored element.
  assertFacing(root, pf, `${job.template} card`);

  const noPic = Object.entries(faces)
    .filter(([, f]) => f.avatar && !f.avatar.hasImage).map(([side]) => side);
  if (noPic.length)
    log(`     ! no profile picture on the ${noPic.join(' and ')} — the add-contact ` +
                `target is the empty placeholder frame. Import or upload an avatar for a real one.`);
  return { root, CARD_W, CARD_H, S, fonts, noPic, touchReport, userIdFields,
         dilations: [...textMats.keys()].map(Number).sort((a,b)=>a-b) };
}

// ──────────────────────── export.mjs ────────────────────────
// Export the card on screen as a .resonitepackage, entirely in the page.
//
//   const { blob, filename, report } = await exportResonite({ fields, onProgress });
//
// The whole pipeline: measure both faces and rasterise their plates (capture.mjs), fetch the
// typefaces they use (fonts.mjs), build the slot tree (../scene.mjs — the same construction the
// Node build runs), and encode it (encoder.mjs over pack.mjs). Nothing is uploaded; the only
// requests are for the font files, and they go to the Google Fonts repository.








const safeName = (s) => (String(s || '').trim().replace(/[^A-Za-z0-9._-]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'dropcard');

/**
 * @param fields      { Name, Nickname } as the card currently shows them — used to find the
 *                    name run that becomes an add-contact target
 * @param template    the template's display name, for the item's name in world
 * @param onProgress  (step, detail) for a status line; every step is a network-free local
 *                    operation except 'fonts'
 * @param withOverlay draw the hover label on each add-contact target
 * @param bake        merge the card's artwork into one texture per side instead of rebuilding
 *                    it as editable elements. Needs no typefaces, so it makes no requests.
 */
async function exportResonite({ fields = {}, template = 'Card', bake = false,
                                       onProgress = () => {}, withOverlay = true } = {}) {
  const notes = [];
  const log = (m) => { notes.push(String(m).trim()); onProgress('note', String(m).trim()); };

  onProgress('capture', 'reading the card');
  const { faces, imageFor } = await captureCard(fields, { bake });
  if (!faces.front) throw new Error('no front face on the page to export');

  if (!bake) onProgress('fonts', 'fetching the typefaces');
  const fontFor = fontLoader(log);
  const job = { template, faces, fields };

  let theme = null, overlayFor = null;
  if (withOverlay) {
    theme = await cardTheme(imageFor('bg', 'front'), job);
    overlayFor = (o) => renderOverlay(o);
  }

  onProgress('build', 'laying out the card in world');
  const { pf, asset, assets, embeds } = newEncoder();
  const card = await cardRoot({ pf, asset, assets, embeds, job, imageFor, sha256, fontFor,
                                theme, overlayFor, userId: '', bake, log });
  card.root.ID = pf.rootId;

  onProgress('encode', 'writing the package');
  const result = await pf.exportPackage({ name: `dropcard — ${template}`, root: card.root,
    assets, embeddedAssets: embeds, typeVersions: TV });

  const base = safeName(fields.Nickname || fields.Name || 'dropcard');
  return {
    blob: new Blob([result.bytes], { type: 'application/octet-stream' }),
    filename: `${base}-${safeName(template).toLowerCase()}${bake ? '-baked' : ''}.resonitepackage`,
    report: {
      widthMM: +(card.CARD_W * 1000).toFixed(1), heightMM: +(card.CARD_H * 1000).toFixed(1),
      fonts: card.fonts.size, embedded: embeds.length, bytes: result.bytes.length,
      contacts: card.touchReport.length, noPicture: card.noPic, notes, baked: bake,
    },
  };
}

/** The whole thing, plus the download. */
async function downloadResonite(opts = {}) {
  const { blob, filename, report } = await exportResonite(opts);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
  return { filename, report };
}

// ──────────────────────── ui.mjs ────────────────────────
// A status line for the export, owned by this bundle rather than by the app.
//
// Building a package takes a few seconds and reaches the network for typefaces, so a button
// that silently does nothing for four seconds reads as broken. Keeping the UI here means the
// patch into index.html stays to one handler swap, and everything with behaviour in it lives
// where it can be tested.
//
// Colours come from the app's own custom properties where they exist, so it follows the theme,
// with plain fallbacks for when this is dropped into a bare page.



const CSS = `
.dc-res-toast{position:fixed;right:18px;bottom:18px;z-index:2147483000;max-width:min(380px,calc(100vw - 36px));
  display:flex;gap:10px;align-items:flex-start;padding:12px 14px;border-radius:12px;
  font:500 13px/1.45 var(--font-sans,system-ui,-apple-system,"Segoe UI",sans-serif);
  color:var(--color-text,#e9e9f2);background:var(--color-surface,#1b1b24);
  border:1px solid var(--color-divider,#33333f);box-shadow:0 10px 30px rgba(0,0,0,.35);
  opacity:0;transform:translateY(8px);transition:opacity .18s ease,transform .18s ease}
.dc-res-toast[data-in]{opacity:1;transform:none}
.dc-res-toast b{display:block;font-weight:650;margin-bottom:2px}
.dc-res-toast small{display:block;opacity:.75;font-weight:450;margin-top:3px}
.dc-res-toast[data-kind=err]{border-color:#c0485a}
.dc-res-toast[data-kind=err] b{color:#ff8fa0}
.dc-res-dot{flex:none;width:9px;height:9px;border-radius:50%;margin-top:5px;
  background:var(--color-accent,#7755cc)}
.dc-res-toast[data-kind=work] .dc-res-dot{animation:dc-res-pulse 1s ease-in-out infinite}
.dc-res-toast[data-kind=ok] .dc-res-dot{background:#46b978}
.dc-res-toast[data-kind=err] .dc-res-dot{background:#e0566e}
.dc-res-x{flex:none;margin:-4px -6px 0 auto;padding:4px 6px;border:0;background:none;cursor:pointer;
  color:inherit;opacity:.55;font-size:15px;line-height:1;font-family:inherit}
.dc-res-x:hover{opacity:1}
@keyframes dc-res-pulse{0%,100%{opacity:.35}50%{opacity:1}}
@media (prefers-reduced-motion:reduce){.dc-res-toast{transition:none}
  .dc-res-toast[data-kind=work] .dc-res-dot{animation:none}}
`;

let node = null, hideTimer = 0;

function toast() {
  if (node && node.isConnected) return node;
  if (!document.getElementById('dc-res-style')) {
    const s = document.createElement('style');
    s.id = 'dc-res-style'; s.textContent = CSS;
    document.head.appendChild(s);
  }
  node = document.createElement('div');
  node.className = 'dc-res-toast';
  node.setAttribute('role', 'status');
  node.innerHTML = '<span class="dc-res-dot"></span><span class="dc-res-body"></span>' +
                   '<button class="dc-res-x" type="button" aria-label="Dismiss">✕</button>';
  node.querySelector('.dc-res-x').addEventListener('click', hide);
  document.body.appendChild(node);
  requestAnimationFrame(() => node && node.setAttribute('data-in', ''));
  return node;
}

function show(kind, title, detail, autoHideMs) {
  const t = toast();
  t.dataset.kind = kind;
  t.querySelector('.dc-res-body').innerHTML = '';
  const b = document.createElement('b'); b.textContent = title;
  t.querySelector('.dc-res-body').appendChild(b);
  if (detail) { const s = document.createElement('small'); s.textContent = detail;
                t.querySelector('.dc-res-body').appendChild(s); }
  t.querySelector('.dc-res-x').style.display = kind === 'work' ? 'none' : '';
  clearTimeout(hideTimer);
  if (autoHideMs) hideTimer = setTimeout(hide, autoHideMs);
}

function hide() {
  clearTimeout(hideTimer);
  const t = node;
  if (!t) return;
  t.removeAttribute('data-in');
  setTimeout(() => { if (t === node) { t.remove(); node = null; } }, 220);
}

const STEP = {
  capture: 'Reading the card…',
  fonts: 'Fetching the typefaces…',
  build: 'Laying the card out in world…',
  encode: 'Writing the package…',
};

/**
 * Export and download, with the status line. Errors are shown rather than thrown, since there
 * is nothing above this to catch them.
 * @returns the report on success, or null if it failed
 */
async function downloadWithStatus(opts = {}) {
  const label = opts.bake ? 'Baking the card' : 'Building the card';
  show('work', label, STEP.capture);
  try {
    const { filename, report } = await downloadResonite({
      ...opts,
      onProgress: (step, detail) => {
        if (step === 'note') return;                 // notes are reported at the end
        show('work', label, STEP[step] || detail);
      },
    });
    const bits = [`${report.widthMM}×${report.heightMM}mm`];
    if (!report.baked) bits.push(`${report.fonts} font${report.fonts === 1 ? '' : 's'}`);
    bits.push(`${(report.bytes / 1e6).toFixed(1)} MB`);
    const note = report.noPicture?.length
      ? 'No profile picture, so add-contact points at the empty frame.' : '';
    show('ok', `Saved ${filename}`, `${bits.join(' · ')}. Drag it into Resonite.${note ? ' ' + note : ''}`, 9000);
    return report;
  } catch (e) {
    console.error('[dropcard] Resonite export failed', e);
    const msg = String((e && e.message) || e);
    show('err', 'Export failed',
         /fetch|network|Failed to fetch|TrueType/i.test(msg)
           ? 'Could not fetch the typefaces this card uses. Check your connection, or use ' +
             '"Export baked", which needs no fonts.'
           : msg.slice(0, 200));
    return null;
  }
}

window.dropcardResonite = { exportResonite, downloadResonite, downloadWithStatus };
})();
